//! JSON schemas generated by `#[openai_schema]` and `#[openai_function]`.
// Types and functions here are only used for their schema.
#![allow(dead_code)]
use open_client::chat::Tool;
use open_client::{OpenAISchema, openai_function, openai_schema};
use serde_json::json;

#[openai_schema]
/// How urgent a ticket is
enum Severity {
    Low,
    High,
    Critical,
}

#[openai_schema]
struct Comment {
    author: String,
    likes: u32,
}

#[openai_schema]
/// A support ticket
struct Ticket {
    /// One line summary
    title: String,
    severity: Severity,
    /// Hours spent so far
    hours: f64,
    resolved: bool,
    tags: Vec<String>,
    comments: Vec<Comment>,
    /// Who is working on it
    assignee: Option<String>,
    escalation: Option<Severity>,
}

#[test]
fn struct_schema_is_strict() {
    let severity = json!({
        "type": "string",
        "description": "How urgent a ticket is",
        "enum": ["Low", "High", "Critical"]
    });
    assert_eq!(Severity::openai_schema(), severity);
    assert_eq!(
        Ticket::openai_schema(),
        json!({
            "type": "object",
            "description": "A support ticket",
            "properties": {
                "title": {"type": "string", "description": "One line summary"},
                "severity": severity,
                "hours": {"type": "number", "description": "Hours spent so far"},
                "resolved": {"type": "boolean"},
                "tags": {"type": "array", "items": {"type": "string"}},
                "comments": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "author": {"type": "string"},
                            "likes": {"type": "integer"}
                        },
                        "required": ["author", "likes"],
                        "additionalProperties": false
                    }
                },
                // Optional fields are nullable but required, as strict mode needs every field
                "assignee": {"type": ["string", "null"], "description": "Who is working on it"},
                "escalation": {"anyOf": [severity, {"type": "null"}]}
            },
            "required": ["title", "severity", "hours", "resolved", "tags", "comments", "assignee", "escalation"],
            "additionalProperties": false
        })
    );
}

#[openai_function]
/// Books a meeting room.
/// Returns the booking id.
fn book_room(
    /// Room name, e.g. "Everest"
    room: String,
    /// Length in minutes
    minutes: u32,
    /// Optional note shown on the room display
    note: Option<String>,
) -> String {
    format!("{room}-{minutes}-{}", note.unwrap_or_default())
}

#[openai_function]
fn no_docs_no_arguments() {}

mod tools {
    use super::*;
    /// The generated `tools::local_time` struct has the visibility of the function.
    #[openai_function]
    pub(crate) fn local_time(city: String) -> String {
        format!("12:00 in {city}")
    }
}

#[test]
fn function_schema() {
    assert_eq!(
        book_room::openai_schema(),
        json!({
            "name": "book_room",
            "description": "Books a meeting room.\nReturns the booking id.",
            "parameters": {
                "type": "object",
                "properties": {
                    "room": {"type": "string", "description": "Room name, e.g. \"Everest\""},
                    "minutes": {"type": "integer", "description": "Length in minutes"},
                    "note": {"type": ["string", "null"], "description": "Optional note shown on the room display"}
                },
                "required": ["room", "minutes", "note"],
                "additionalProperties": false
            }
        })
    );
    // No "description" without doc comments
    assert_eq!(
        no_docs_no_arguments::openai_schema(),
        json!({
            "name": "no_docs_no_arguments",
            "parameters": {"type": "object", "properties": {}, "required": [], "additionalProperties": false}
        })
    );
    assert_eq!(tools::local_time::openai_schema()["name"], "local_time");
}

#[test]
fn parse_arguments() {
    assert_eq!(
        book_room::parse_arguments(&json!({"room": "Everest", "minutes": 30, "note": null}))
            .unwrap(),
        ("Everest".to_string(), 30, None)
    );
    // An optional argument may also be left out
    assert_eq!(
        book_room::parse_arguments(&json!({"room": "Everest", "minutes": 30})).unwrap(),
        ("Everest".to_string(), 30, None)
    );
    assert!(book_room::parse_arguments(&json!({"room": "Everest"})).is_err());
    assert!(book_room::parse_arguments(&json!({"room": "Everest", "minutes": -1})).is_err());
}

#[test]
fn tool_from_schema() {
    let tool = Tool::Function(book_room::openai_schema());
    assert_eq!(tool.name(), Some("book_room"));
    let tool = serde_json::to_value(&tool).unwrap();
    assert_eq!(tool["type"], "function");
    assert_eq!(tool["function"], book_room::openai_schema());
}
